// Asks Casbin whether the current user may call this route.\nasync fn authorize(State(enforcer): State<SharedEnforcer>, req: Request, next: Next) -> Response {\n    // Replace this with the user from your session or JWT.\n    let user = req\n        .headers()\n        .get("x-user")\n        .and_then(|v| v.to_str().ok())\n        .unwrap_or("")\n        .to_string();\n    // Inside a nested router req.uri() has the /api prefix stripped, so use the original URI.\n    let path = match req.extensions().get::<OriginalUri>() {\n        Some(OriginalUri(uri)) => uri.path().to_string(),\n        None => req.uri().path().to_string(),\n    };\n    let method = req.method().as_str().to_string();\n\n    match enforcer.read().await.enforce((user, path, method)) {\n        Ok(true) => next.run(req).await,\n        Ok(false) => (StatusCode::FORBIDDEN, Json(json!({ "error": "forbidden" }))).into_response(),\n        Err(e) => (StatusCode::INTERNAL_SERVER_ERROR, Json(json!({ "error": e.to_string() }))).into_response(),\n    }\n}\n\nasync fn list_articles() -> Json<Value> {\n    Json(json!({ "articles": [] }))\n}\n\nasync fn create_article() -> (StatusCode, Json<Value>) {\n    (StatusCode::CREATED, Json(json!({ "created": true })))\n}\n\nasync fn update_article(Path(id): Path<u32>) -> Json<Value> {\n    Json(json!({ "updated": id }))\n}\n\nasync fn delete_article(Path(id): Path<u32>) -> Json<Value> {\n    Json(json!({ "deleted": id }))\n}\n\n#[tokio::main]\nasync fn main() {\n    let enforcer = Enforcer::new("model.conf", "policy.csv").await.unwrap();\n    let enforcer: SharedEnforcer = Arc::new(RwLock::new(enforcer));\n\n    let api = Router::new()\n        .route("/articles", get(list_articles).post(create_article))\n        .route("/articles/{id}", axum::routing::put(update_article).delete(delete_article))\n        .route_layer(middleware::from_fn_with_state(enforcer.clone(), authorize));\n\n    let app = Router::new().nest("/api", api).with_state(enforcer);\n\n    let listener = tokio::net::TcpListener::bind("0.0.0.0:8080").await.unwrap();\n    axum::serve(listener, app).await.unwrap();\n}\n'})}),"\n",(0,t.jsx)(n.admonition,{type:"caution",children:(0,t.jsxs)(n.p,{children:["\u0412\u043d\u0443\u0442\u0440\u0438 \u0440\u043e\u0443\u0442\u0435\u0440\u0430, \u0434\u043e\u0431\u0430\u0432\u043b\u0435\u043d\u043d\u043e\u0433\u043e \u0447\u0435\u0440\u0435\u0437 ",(0,t.jsx)(n.code,{children:"nest"}),", \u0443 ",(0,t.jsx)(n.code,{children:"req.uri()"})," \u0443\u0434\u0430\u043b\u0435\u043d \u043f\u0440\u0435\u0444\u0438\u043a\u0441: \u0437\u0430\u043f\u0440\u043e\u0441 \u043a ",(0,t.jsx)(n.code,{children:"/api/articles"})," \u043f\u0440\u0438\u0445\u043e\u0434\u0438\u0442 \u043a\u0430\u043a ",(0,t.jsx)(n.code,{children:"/articles"}),", \u0447\u0442\u043e \u043d\u0435 \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u0435\u0442 \u043d\u0438 \u043e\u0434\u043d\u043e\u043c\u0443 \u043f\u0440\u0430\u0432\u0438\u043b\u0443 \u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0438. \u041f\u043e\u044d\u0442\u043e\u043c\u0443 middleware \u0447\u0438\u0442\u0430\u0435\u0442 ",(0,t.jsx)(n.code,{children:"OriginalUri"}),". \u0415\u0441\u043b\u0438 \u0432\u0430\u0448 middleware \u043e\u0442\u043a\u043b\u043e\u043d\u044f\u0435\u0442 \u0432\u0441\u0435 \u0437\u0430\u043f\u0440\u043e\u0441\u044b, \u043f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435, \u043a\u0430\u043a\u043e\u0439 \u043f\u0443\u0442\u044c \u043e\u043d \u043f\u0435\u0440\u0435\u0434\u0430\u0435\u0442 \u0432 Casbin."]})}),"\n",(0,t.jsx)(n.admonition,{type:"note",children:(0,t.jsxs)(n.p,{children:["\u0417\u0430\u0433\u043e\u043b\u043e\u0432\u043e\u043a ",(0,t.jsx)(n.code,{children:"X-User"})," \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f \u0434\u043b\u044f \u043a\u0440\u0430\u0442\u043a\u043e\u0441\u0442\u0438 \u043f\u0440\u0438\u043c\u0435\u0440\u0430. Casbin \u043e\u0442\u0432\u0435\u0447\u0430\u0435\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u0437\u043